import{_ as t,o as d,c as s,a2 as o}from"./chunks/framework.DGu13UIe.js";const a="/bagent/lessons/46-reminder-injection/image1.png",i="/bagent/lessons/46-reminder-injection/image2.png",k=JSON.parse('{"title":"第 46 课 · 用户消息 Reminder 注入","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/46-reminder-injection/doc.md"},"headers":[],"relativePath":"chapters/46-reminder-injection.md","filePath":"chapters/46-reminder-injection.md"}'),n={name:"chapters/46-reminder-injection.md"};function r(c,e,l,h,p,g){return d(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="第-46-课-·-用户消息-reminder-注入" tabindex="-1">第 46 课 · 用户消息 Reminder 注入 <a class="header-anchor" href="#第-46-课-·-用户消息-reminder-注入" aria-label="Permalink to &quot;第 46 课 · 用户消息 Reminder 注入&quot;">​</a></h1><p><strong>约 30 分钟</strong> · <a href="/bagent/chapters/45-web-search.html">第 45 课</a> 之后 · <strong>独立插件</strong></p><p>长对话里，模型容易「忘掉」系统提示里的细节：该用 <code>ask_user_question</code> 时却在正文里盘问、路径写成相对路径、该等审批时自作主张。本课在 <a href="/bagent/chapters/45-web-search.html">第 45 课</a> 能力之上，增加 <strong>reminder 注入</strong>——把关键规则悄悄附在每条发往 API 的用户消息后面，用户界面仍只显示原文。</p><hr><h2 id="_1-思路" tabindex="-1">1. 思路 <a class="header-anchor" href="#_1-思路" aria-label="Permalink to &quot;1. 思路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>存什么</th><th>用户看到什么</th></tr></thead><tbody><tr><td><code>history</code></td><td>干净的用户原文</td><td>—</td></tr><tr><td>发往 LLM 的 payload</td><td>原文 + <code>&lt;reminder&gt;…&lt;/reminder&gt;</code></td><td>模型读到规则</td></tr><tr><td>侧边栏 / webview</td><td>同 <code>history</code>（再经 <code>stripReminder</code> 兜底）</td><td>只有原文</td></tr></tbody></table><p>标签形如：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">reminder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">1. 不要使用markdown语法，使用纯文本</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2. 缺关键信息才能继续任务时，必须用 ask_user_question …</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">3. 保持简洁…</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">4. 不要透露敏感信息…</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">reminder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>模型会把 <code>&lt;reminder&gt;</code> 当作本轮补充约束；用户输入框与气泡里不会出现这段文字。</p><hr><h2 id="_2-注入时机" tabindex="-1">2. 注入时机 <a class="header-anchor" href="#_2-注入时机" aria-label="Permalink to &quot;2. 注入时机&quot;">​</a></h2><p><code>agent/stream.ts</code> 在 <code>fetch</code> 前调用 <code>messagesForApi(history)</code>：</p><ul><li><code>history</code> 里每条 <code>user</code> 消息保持用户输入的原样（<code>loop.ts</code> 的 <code>push</code> 不改写）。</li><li>仅 <strong>当前轮最新一条</strong> <code>user</code> 消息在构建 API <code>messages</code> 时调用 <code>augmentUserMessage()</code>。</li><li>同一轮里若模型连续调工具、多次请求 API，每次都会给这条 user 消息重新附上 reminder，减轻中途「跑偏」。</li></ul><hr><h2 id="_3-代码位置" tabindex="-1">3. 代码位置 <a class="header-anchor" href="#_3-代码位置" aria-label="Permalink to &quot;3. 代码位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>agent/system.ts</code></td><td><code>BEHAVIOR_RULES</code>（四条行为准则，system 与 reminder 共用）</td></tr><tr><td><code>agent/reminder.ts</code></td><td><code>augmentUserMessage()</code>、<code>stripReminder()</code></td></tr><tr><td><code>agent/plan.ts</code></td><td><code>plan_operate</code>：<code>~/.bagent/{项目名}/{name}.md</code> 待办清单</td></tr><tr><td><code>agent/stream.ts</code></td><td><code>messagesForApi()</code>，仅 API 路径注入</td></tr><tr><td><code>src/utils/reminder.ts</code></td><td>扩展进程侧 <code>stripReminder()</code>（与 agent 逻辑一致）</td></tr><tr><td><code>src/sidebar.ts</code></td><td>webview 展示前去掉 <code>&lt;reminder&gt;</code> 块（安全网）</td></tr></tbody></table><p>reminder 正文与 <code>system.ts</code> 里 <code>BEHAVIOR_RULES</code> 完全相同（上述四条）；工具说明、路径与审批仍只在 system 里写一次，不重复进 reminder。</p><hr><h2 id="_4-与第-45-课关系" tabindex="-1">4. 与第 45 课关系 <a class="header-anchor" href="#_4-与第-45-课关系" aria-label="Permalink to &quot;4. 与第 45 课关系&quot;">​</a></h2><ul><li><strong>第 45 课</strong>：联网、<code>ask_user_question</code>、只读自动放行</li><li><strong>第 46 课</strong>：fork 45 + reminder 注入；<strong>不修改</strong> 40 / 44 / 45</li></ul><p>其余工具、审批、追问流程与第 45 课相同。本课另增 <strong><code>plan_operate</code></strong>：Agent 可把多步任务写成 Markdown 待办，落在 <strong><code>~/.bagent/{项目名}/{name}.md</code></strong>（与 <code>deepseek-api-key</code> 等同在用户目录，<strong>不在</strong>工作区里建 <code>.bagent</code>）。<code>{项目名}</code> 为当前 cwd 目录名的安全化形式；<strong><code>name</code></strong> 区分同一项目下的多份计划（如 <code>refactor-auth</code>、<code>fix-bug-42</code>）。</p><table tabindex="0"><thead><tr><th>method</th><th>作用</th></tr></thead><tbody><tr><td><code>read</code></td><td>读取当前计划（返回 <code>todos</code> / <code>markdown</code>）；<code>content</code> 可空</td></tr><tr><td><code>new</code> / <code>replace</code></td><td>整表写入或重写该 <code>name</code> 的计划</td></tr><tr><td><code>update</code></td><td>合并：<code>- [x]</code> 勾选、增补新行、<code>- [-] 条目</code> 删除该项</td></tr><tr><td><code>delete</code></td><td><code>content</code> 为空删文件；否则按条目文本删除</td></tr></tbody></table><p>改计划前应先 <strong><code>read</code></strong>；大改条目用 <strong><code>replace</code></strong> 整表重写，小改用 <strong><code>update</code></strong>。</p><p><code>content</code> 可为完整 Markdown，或每行一条待办（自动补成 <code>- [ ] …</code>）。写入 <code>~/.bagent</code> 由 Agent 自管，<strong>自动放行</strong>，不走 <code>write_file</code> 审批。</p><p><strong>UI</strong>：<code>plan_operate</code> 成功后额外发出 <code>PlanUpdated</code> 事件；侧边栏渲染待办卡片（勾选状态、进度条 <code>done/total</code>），不再把 JSON 工具结果当普通一行刷出来。终端 <code>npm run ch46</code> 同样打印清单与进度。</p><p><img src="`+a+'" alt="计划卡片与 web_search"></p><p>多步任务里 <code>refine-summer-plan</code> 计划卡片：<strong>1/6</strong> 进度、条目勾选；<code>web_search</code> 绿边自动放行；思考块折叠在正文上方。计划落在 <code>~/.bagent/{项目名}/</code>，不污染工作区。</p><p><img src="'+i+`" alt="ask_user_question 与联网追问"></p><p>同一轮对话更早片段：用户说「再加一个清迈的行程」，Agent 用 <strong><code>ask_user_question</code></strong> 卡片追问（非正文盘问），用户答「有」后再 <strong><code>web_search</code></strong>；左侧编辑器里是 <code>write_file</code> 写出的 <code>summer-plan.md</code>。</p><hr><h2 id="_5-vs-code-动手" tabindex="-1">5. VS Code 动手 <a class="header-anchor" href="#_5-vs-code-动手" aria-label="Permalink to &quot;5. VS Code 动手&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch46:compile</span></span></code></pre></div><ol><li>打开 <strong><code>lessons/46-reminder-injection</code></strong> → <strong>F5</strong></li><li><code>bagent: 打开 Agent 面板（第 46 课）</code></li><li>多轮对话后，观察模型是否仍倾向用 <code>ask_user_question</code>、绝对路径</li><li>确认聊天气泡里没有 <code>&lt;reminder&gt;</code> 字样</li></ol><p>调试 API 时可在 <code>messagesForApi</code> 处打日志，对比 <code>history</code> 与发往 DeepSeek 的 <code>messages</code>。</p><hr><h2 id="_6-终端动手" tabindex="-1">6. 终端动手 <a class="header-anchor" href="#_6-终端动手" aria-label="Permalink to &quot;6. 终端动手&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch46</span></span></code></pre></div><p>终端同样走 <code>streamEvents</code> → <code>messagesForApi</code>，注入行为与插件一致。</p><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] <code>history</code> 里 user 消息无 <code>&lt;reminder&gt;</code>？</li><li>[ ] 每次 API 请求里最新 user 消息带 reminder？</li><li>[ ] 侧边栏用户气泡不显示 reminder 块？</li><li>[ ] 多轮工具调用后模型仍遵守追问 / 路径规则？</li><li>[ ] 多步任务时 Agent 会用 <code>plan_operate</code>（带 <code>name</code>），且 <code>~/.bagent/…/{name}.md</code> 为 Markdown 待办？</li><li>[ ] 侧边栏出现计划卡片，能看到条目勾选与 <code>done/total</code> 进度？</li></ul><hr><p><a href="/bagent/chapters/45-web-search.html">← 第 45 课</a></p>`,43)])])}const b=t(n,[["render",r]]);export{k as __pageData,b as default};
